import { Injectable, UnauthorizedException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import * as bcrypt from 'bcrypt';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class AuthService {
  constructor(private readonly prisma: PrismaService, private readonly jwt: JwtService) {}
  async login(email: string, password: string) { const user = await this.prisma.user.findFirst({ where: { email }, include: { roles: { include: { role: true } } } }); if (!user || user.status !== 'ACTIVE' || !(await bcrypt.compare(password, user.passwordHash))) throw new UnauthorizedException('بيانات الدخول غير صحيحة'); const payload = { sub: user.id, organizationId: user.organizationId, roles: user.roles.map((assignment: { role: { name: string } }) => assignment.role.name) }; return { accessToken: await this.jwt.signAsync(payload), user: { id: user.id, name: user.name, email: user.email, roles: payload.roles } }; }
}
